CREATE TABLE IF NOT EXISTS categories(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name varchar(100) NOT NULL UNIQUE,icon varchar(20),section_slug varchar(64) REFERENCES business_sections(slug),published boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS media_content(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title varchar(120) NOT NULL,type varchar(15) NOT NULL CHECK(type IN('HERO','VIDEO','IMAGE')),url text NOT NULL,category varchar(100),subtitle varchar(500),published boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS promotions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title varchar(130) NOT NULL,description text NOT NULL DEFAULT '',category varchar(100),image_url text,starts_on date,ends_on date,published boolean NOT NULL DEFAULT false,information_only boolean NOT NULL DEFAULT true);
